import sys
def solve(n, edges):
    from collections import defaultdict
    adj = defaultdict(list); radj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v); radj[v].append(u)
    visited = [False] * (n + 1)
    order = []
    def dfs1(v):
        stack = [(v, 0)]
        while stack:
            node, i = stack[-1]
            if i == 0: visited[node] = True
            if i < len(adj[node]):
                stack[-1] = (node, i + 1)
                nb = adj[node][i]
                if not visited[nb]: stack.append((nb, 0))
            else: order.append(node); stack.pop()
    for i in range(1, n + 1):
        if not visited[i]: dfs1(i)
    comp = [-1] * (n + 1); c = 0
    def dfs2(v, c):
        stack = [v]
        while stack:
            node = stack.pop(); comp[node] = c
            for nb in radj[node]:
                if comp[nb] == -1: stack.append(nb)
    for v in reversed(order):
        if comp[v] == -1: dfs2(v, c); c += 1
    if c == 1: return "0"
    in0 = [0] * c; out0 = [0] * c
    for u in range(1, n + 1):
        for v in adj[u]:
            if comp[u] != comp[v]: out0[comp[u]] += 1; in0[comp[v]] += 1
    return str(max(sum(1 for x in in0 if x == 0), sum(1 for x in out0 if x == 0)))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    n, m = int(data[idx]), int(data[idx+1]); idx += 2
    edges = []
    for _ in range(m):
        edges.append((int(data[idx]), int(data[idx+1]))); idx += 2
    print(solve(n, edges))

